package server

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"sync/atomic"
	"time"

	"github.com/Autumn-27/artex/agent"
	"github.com/Autumn-27/artex/db"
	actool "github.com/Autumn-27/norma/tool"
)

// A receipt is generated by the ARTEX server around a custom-tool invocation.
// The wrapped script/command output remains evidence, but it is intentionally
// not authoritative for whether the runner actually completed. In particular,
// a script printing {"success":true} never changes Runner.Outcome.
const customToolReceiptVersion = 1

type customToolReceiptEnvelope struct {
	Receipt customToolExecutionReceipt `json:"artex_execution_receipt"`
	Output  string                     `json:"output,omitempty"`
}

type customToolExecutionReceipt struct {
	Version        int                        `json:"version"`
	ReceiptID      string                     `json:"receipt_id"`
	RunID          string                     `json:"run_id,omitempty"`
	Tool           customToolReceiptTool      `json:"tool"`
	Scenario       *customToolReceiptScenario `json:"scenario,omitempty"`
	InputSHA256    string                     `json:"input_sha256"`
	OutputSHA256   string                     `json:"output_sha256"`
	StartedAt      time.Time                  `json:"started_at"`
	FinishedAt     time.Time                  `json:"finished_at"`
	DurationMillis int64                      `json:"duration_ms"`
	Runner         customToolReceiptRunner    `json:"runner"`
}

type customToolReceiptTool struct {
	Key              string `json:"key"`
	Kind             string `json:"kind"`
	DefinitionSHA256 string `json:"definition_sha256"`
}

type customToolReceiptScenario struct {
	ID            string `json:"id"`
	ProfileState  string `json:"profile_state"`
	ProfileSHA256 string `json:"profile_sha256"`
}

type customToolReceiptRunner struct {
	Outcome       string `json:"outcome"` // completed | failed | timed_out | cancelled
	ResultIsError bool   `json:"result_is_error"`
	ErrorClass    string `json:"error_class,omitempty"`
}

var customToolReceiptSequence uint64

// executeCustomToolWithReceipt preserves the original result body, but wraps it
// in a server-owned envelope. The envelope is deliberately descriptive rather
// than a goal proof: it does not establish a target-side effect, a vulnerability,
// or a SOC alert.
func executeCustomToolWithReceipt(ctx context.Context, t *db.Tool, params map[string]any, tc *actool.ToolContext, run func() (actool.Result, error)) (actool.Result, error) {
	started := time.Now().UTC()
	result, runErr := run()
	finished := time.Now().UTC()

	rawOutput := result.Flatten()
	if runErr != nil && strings.TrimSpace(rawOutput) == "" {
		rawOutput = runErr.Error()
	}
	runInfo := agent.RunInfoFrom(ctx)
	receipt := customToolExecutionReceipt{
		Version:        customToolReceiptVersion,
		ReceiptID:      nextCustomToolReceiptID(started),
		RunID:          receiptRunID(params),
		Tool:           customToolReceiptTool{Key: t.Key, Kind: t.Kind, DefinitionSHA256: customToolDefinitionSHA256(t)},
		InputSHA256:    customToolValueSHA256(params),
		OutputSHA256:   sha256Hex([]byte(rawOutput)),
		StartedAt:      started,
		FinishedAt:     finished,
		DurationMillis: finished.Sub(started).Milliseconds(),
		Runner:         customToolRunnerReceipt(ctx, result.IsError, runErr),
	}
	if runInfo.ScenarioID != "" {
		receipt.Scenario = &customToolReceiptScenario{
			ID:            runInfo.ScenarioID,
			ProfileState:  runInfo.ScenarioProfileState,
			ProfileSHA256: runInfo.ScenarioProfileSHA256,
		}
	}
	payload, marshalErr := json.Marshal(customToolReceiptEnvelope{Receipt: receipt, Output: rawOutput})
	if marshalErr != nil {
		return actool.Errorf("custom-tool execution receipt encoding failed: " + marshalErr.Error()), nil
	}
	wrapped := actool.Text(actool.Capture(tc, string(payload)))
	wrapped.IsError = result.IsError || runErr != nil
	// Convert an executor error to an errored result so a paired tool_result is
	// persisted and contains the receipt. The original error class is retained in
	// the envelope; callers must not treat an errored result as an execution.
	return wrapped, nil
}

func customToolRunnerReceipt(ctx context.Context, resultIsError bool, runErr error) customToolReceiptRunner {
	switch {
	case errors.Is(runErr, context.DeadlineExceeded), errors.Is(ctx.Err(), context.DeadlineExceeded):
		return customToolReceiptRunner{Outcome: "timed_out", ResultIsError: true, ErrorClass: "deadline_exceeded"}
	case errors.Is(runErr, context.Canceled), errors.Is(ctx.Err(), context.Canceled):
		return customToolReceiptRunner{Outcome: "cancelled", ResultIsError: true, ErrorClass: "cancelled"}
	case runErr != nil:
		return customToolReceiptRunner{Outcome: "failed", ResultIsError: true, ErrorClass: "runner_error"}
	case resultIsError:
		return customToolReceiptRunner{Outcome: "failed", ResultIsError: true, ErrorClass: "tool_error"}
	default:
		return customToolReceiptRunner{Outcome: "completed", ResultIsError: false}
	}
}

func customToolDefinitionSHA256(t *db.Tool) string {
	// Include the complete editable definition rather than only exec code. The
	// hash makes a later change detectable; a future profile/snapshot store will
	// retain the corresponding definition bytes for full reconstruction.
	payload := struct {
		Key         string          `json:"key"`
		Description string          `json:"description"`
		Schema      json.RawMessage `json:"schema"`
		Agents      []string        `json:"agents"`
		Enabled     bool            `json:"enabled"`
		Kind        string          `json:"kind"`
		Exec        json.RawMessage `json:"exec"`
		Deferred    bool            `json:"deferred"`
	}{
		Key: t.Key, Description: t.Description, Schema: t.Schema, Agents: t.Agents,
		Enabled: t.Enabled, Kind: t.Kind, Exec: t.Exec, Deferred: t.Deferred,
	}
	b, err := json.Marshal(payload)
	if err != nil {
		return sha256Hex([]byte(fmt.Sprintf("invalid-custom-tool:%s", t.Key)))
	}
	return sha256Hex(b)
}

func customToolValueSHA256(v any) string {
	b, err := json.Marshal(v)
	if err != nil {
		return sha256Hex([]byte("unserializable-custom-tool-input"))
	}
	return sha256Hex(b)
}

func receiptRunID(params map[string]any) string {
	v, ok := params["run_id"]
	if !ok {
		return ""
	}
	s, ok := v.(string)
	if !ok {
		return ""
	}
	return strings.TrimSpace(s)
}

func nextCustomToolReceiptID(started time.Time) string {
	seq := atomic.AddUint64(&customToolReceiptSequence, 1)
	return fmt.Sprintf("ctr-%d-%d", started.UnixNano(), seq)
}

func sha256Hex(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}
